// Macros for entities WITH relationships (reduces boilerplate)
// ═════════════════════════════════════════════════════════════════════════════

/// Generate standard relationship methods for a HashMap table implementation.
#[macro_export]
macro_rules! impl_relationship_methods {
    ($table_type:ty, $field_enum:ty) => {
        fn get_relationship(
            &self,
            id: &$crate::types::EntityId,
            field: &$field_enum,
        ) -> Result<Vec<$crate::types::EntityId>, $crate::error::RepositoryError> {
            Ok($crate::database::hashmap_store::junction_get(
                self.resolve_junction(field),
                id,
            ))
        }

        fn get_relationship_many(
            &self,
            ids: &[$crate::types::EntityId],
            field: &$field_enum,
        ) -> Result<
            std::collections::HashMap<$crate::types::EntityId, Vec<$crate::types::EntityId>>,
            $crate::error::RepositoryError,
        > {
            let jn = self.resolve_junction(field);
            let mut map = std::collections::HashMap::new();
            for id in ids {
                map.insert(*id, $crate::database::hashmap_store::junction_get(jn, id));
            }
            Ok(map)
        }

        fn get_relationship_count(
            &self,
            id: &$crate::types::EntityId,
            field: &$field_enum,
        ) -> Result<usize, $crate::error::RepositoryError> {
            Ok(
                $crate::database::hashmap_store::junction_get(self.resolve_junction(field), id)
                    .len(),
            )
        }

        fn get_relationship_in_range(
            &self,
            id: &$crate::types::EntityId,
            field: &$field_enum,
            offset: usize,
            limit: usize,
        ) -> Result<Vec<$crate::types::EntityId>, $crate::error::RepositoryError> {
            let all =
                $crate::database::hashmap_store::junction_get(self.resolve_junction(field), id);
            Ok(all.into_iter().skip(offset).take(limit).collect())
        }

        fn get_relationships_from_right_ids(
            &self,
            field: &$field_enum,
            right_ids: &[$crate::types::EntityId],
        ) -> Result<
            Vec<($crate::types::EntityId, Vec<$crate::types::EntityId>)>,
            $crate::error::RepositoryError,
        > {
            Ok(
                $crate::database::hashmap_store::junction_get_relationships_from_right_ids(
                    self.resolve_junction(field),
                    right_ids,
                ),
            )
        }
    };
}

#[macro_export]
macro_rules! impl_write_relationship_methods {
    ($table_type:ty, $field_enum:ty) => {
        $crate::impl_relationship_methods!($table_type, $field_enum);

        fn set_relationship_multi(
            &mut self,
            field: &$field_enum,
            relationships: Vec<($crate::types::EntityId, Vec<$crate::types::EntityId>)>,
        ) -> Result<(), $crate::error::RepositoryError> {
            for (id, _) in &relationships {
                if !self.relationship_source_exists(id) {
                    return Err($crate::error::RepositoryError::ConstraintViolation(
                        "relationship source does not exist".into(),
                    ));
                }
            }
            self.validate_relationship_updates(field, &relationships, &[])?;
            let jn = self.resolve_junction(field);
            for (left_id, entities) in relationships {
                $crate::database::hashmap_store::junction_set(jn, left_id, entities);
            }
            Ok(())
        }

        fn set_relationship(
            &mut self,
            id: &$crate::types::EntityId,
            field: &$field_enum,
            right_ids: &[$crate::types::EntityId],
        ) -> Result<(), $crate::error::RepositoryError> {
            self.set_relationship_multi(field, vec![(*id, right_ids.to_vec())])
        }

        fn move_relationship_ids(
            &mut self,
            id: &$crate::types::EntityId,
            field: &$field_enum,
            ids_to_move: &[$crate::types::EntityId],
            new_index: i32,
        ) -> Result<Vec<$crate::types::EntityId>, $crate::error::RepositoryError> {
            if !self.relationship_is_ordered(field) {
                return Err($crate::error::RepositoryError::ConstraintViolation(
                    "only ordered relationships can be moved".into(),
                ));
            }
            let current =
                $crate::database::hashmap_store::junction_get(self.resolve_junction(field), id);
            let mut seen = std::collections::HashSet::new();
            if ids_to_move
                .iter()
                .any(|target| !seen.insert(*target) || !current.contains(target))
            {
                return Err($crate::error::RepositoryError::ConstraintViolation(
                    "move requires distinct existing relationship members".into(),
                ));
            }
            self.validate_relationship_updates(field, &[(*id, current)], &[])?;
            if !self.relationship_source_exists(id) {
                return Err($crate::error::RepositoryError::ConstraintViolation(
                    "relationship source does not exist".into(),
                ));
            }
            Ok($crate::database::hashmap_store::junction_move_ids(
                self.resolve_junction(field),
                id,
                ids_to_move,
                new_index,
            ))
        }
    };
}

// ═════════════════════════════════════════════════════════════════════════════
// Leaf entity macro (entities without forward relationships)
// ═════════════════════════════════════════════════════════════════════════════

#[macro_export]
macro_rules! impl_leaf_entity_table {
    (
        entity: $Entity:ident,
        entity_name: $entity_name:expr,
        store_field: $store_field:ident,
        table_trait: $TableTrait:ident,
        table_ro_trait: $TableROTrait:ident,
        table_struct: $TableStruct:ident,
        table_ro_struct: $TableROStruct:ident,
        backward_junctions: [ $( ($bj_field:ident) ),* $(,)? ],
    ) => {
        pub struct $TableStruct<'a> {
            store: &'a $crate::database::hashmap_store::HashMapStore,
        }

        impl<'a> $TableStruct<'a> {
            pub fn new(store: &'a $crate::database::hashmap_store::HashMapStore) -> Self {
                Self { store }
            }
        }

        impl<'a> $TableTrait for $TableStruct<'a> {
            fn create(&mut self, entity: &$Entity) -> Result<$Entity, $crate::error::RepositoryError> {
                self.create_multi(std::slice::from_ref(entity))
                    .and_then(|v| {
                        v.into_iter().next().ok_or_else(|| {
                            $crate::error::RepositoryError::Other(::anyhow::anyhow!(
                                "create: the store returned no row for the entity it was given"
                            ))
                        })
                    })
            }

            fn create_multi(&mut self, entities: &[$Entity]) -> Result<Vec<$Entity>, $crate::error::RepositoryError> {
                let mut created = Vec::with_capacity(entities.len());
                let mut map = $crate::database::hashmap_store::write_or_recover(&self.store.$store_field);

                for entity in entities {
                    let new_entity = if entity.id == $crate::types::EntityId::default() {
                        let id = self.store.next_id($entity_name);
                        $Entity {
                            id,
                            ..entity.clone()
                        }
                    } else {
                        if map.contains_key(&entity.id) {
                            return Err($crate::error::RepositoryError::DuplicateId {
                                entity: stringify!($Entity),
                                id: entity.id,
                            });
                        }
                        entity.clone()
                    };

                    map.insert(new_entity.id, new_entity.clone());
                    created.push(new_entity);
                }
                Ok(created)
            }

            fn get(&self, id: &$crate::types::EntityId) -> Result<Option<$Entity>, $crate::error::RepositoryError> {
                Ok($crate::database::hashmap_store::read_or_recover(&self.store.$store_field).get(id).cloned())
            }

            fn get_multi(&self, ids: &[$crate::types::EntityId]) -> Result<Vec<Option<$Entity>>, $crate::error::RepositoryError> {
                let map = $crate::database::hashmap_store::read_or_recover(&self.store.$store_field);
                Ok(ids.iter().map(|id| map.get(id).cloned()).collect())
            }

            fn get_all(&self) -> Result<Vec<$Entity>, $crate::error::RepositoryError> {
                Ok($crate::database::hashmap_store::read_or_recover(&self.store.$store_field).values().cloned().collect())
            }

            fn update(&mut self, entity: &$Entity) -> Result<$Entity, $crate::error::RepositoryError> {
                self.update_multi(std::slice::from_ref(entity))
                    .and_then(|v| {
                        v.into_iter().next().ok_or_else(|| {
                            $crate::error::RepositoryError::Other(::anyhow::anyhow!(
                                "update: the store returned no row for the entity it was given"
                            ))
                        })
                    })
            }

            fn update_multi(&mut self, entities: &[$Entity]) -> Result<Vec<$Entity>, $crate::error::RepositoryError> {
                let mut map = $crate::database::hashmap_store::write_or_recover(&self.store.$store_field);
                let mut result = Vec::with_capacity(entities.len());
                for entity in entities {
                    map.insert(entity.id, entity.clone());
                    result.push(entity.clone());
                }
                Ok(result)
            }

            fn update_with_relationships(&mut self, entity: &$Entity) -> Result<$Entity, $crate::error::RepositoryError> {
                self.update(entity)
            }

            fn update_with_relationships_multi(&mut self, entities: &[$Entity]) -> Result<Vec<$Entity>, $crate::error::RepositoryError> {
                self.update_multi(entities)
            }

            fn remove(&mut self, id: &$crate::types::EntityId) -> Result<(), $crate::error::RepositoryError> {
                self.remove_multi(std::slice::from_ref(id))
            }

            fn remove_multi(&mut self, ids: &[$crate::types::EntityId]) -> Result<(), $crate::error::RepositoryError> {
                let mut map = $crate::database::hashmap_store::write_or_recover(&self.store.$store_field);
                for id in ids {
                    map.remove(id);
                    $(
                        $crate::database::hashmap_store::delete_from_backward_junction(&self.store.$bj_field, id);
                    )*
                }
                Ok(())
            }
        }

        pub struct $TableROStruct<'a> {
            store: &'a $crate::database::hashmap_store::HashMapStore,
        }

        impl<'a> $TableROStruct<'a> {
            pub fn new(store: &'a $crate::database::hashmap_store::HashMapStore) -> Self {
                Self { store }
            }
        }

        impl<'a> $TableROTrait for $TableROStruct<'a> {
            fn get(&self, id: &$crate::types::EntityId) -> Result<Option<$Entity>, $crate::error::RepositoryError> {
                Ok($crate::database::hashmap_store::read_or_recover(&self.store.$store_field).get(id).cloned())
            }

            fn get_multi(&self, ids: &[$crate::types::EntityId]) -> Result<Vec<Option<$Entity>>, $crate::error::RepositoryError> {
                let map = $crate::database::hashmap_store::read_or_recover(&self.store.$store_field);
                Ok(ids.iter().map(|id| map.get(id).cloned()).collect())
            }

            fn get_all(&self) -> Result<Vec<$Entity>, $crate::error::RepositoryError> {
                Ok($crate::database::hashmap_store::read_or_recover(&self.store.$store_field).values().cloned().collect())
            }
        }
    };
}

// ═════════════════════════════════════════════════════════════════════════════
// Junction index tests (entity-independent, so generated into every project)
// ═════════════════════════════════════════════════════════════════════════════

#[cfg(test)]
mod junction_tests {
    use super::*;
    use crate::error::RepositoryError;

    /// The 2.0.0 check, kept verbatim as the reference: it walks every row of
    /// the junction that is not being replaced. The indexed check must give
    /// the same answer for every junction and every batch.
    fn validate_by_walking(
        junction: &HashMapJunction,
        replacements: &[(EntityId, Vec<EntityId>)],
        scalar: bool,
    ) -> Result<(), RepositoryError> {
        use RepositoryError::ConstraintViolation;
        use std::collections::HashSet;
        let mut owners = HashSet::new();
        for (owner, targets) in replacements {
            if !owners.insert(*owner) {
                return Err(ConstraintViolation(
                    "duplicate source in relationship batch".into(),
                ));
            }
            if scalar && targets.len() > 1 {
                return Err(ConstraintViolation(
                    "to-one relationship accepts at most one target".into(),
                ));
            }
            let mut unique = HashSet::new();
            if targets.iter().any(|id| !unique.insert(*id)) {
                return Err(ConstraintViolation("duplicate relationship target".into()));
            }
        }
        if junction.is_exclusive() {
            let mut used = HashSet::new();
            for (_, targets) in junction.iter().filter(|(id, _)| !owners.contains(id)) {
                used.extend(targets.iter().copied());
            }
            for (_, targets) in replacements {
                if targets.iter().any(|id| !used.insert(*id)) {
                    return Err(ConstraintViolation(
                        "relationship target already belongs to another source".into(),
                    ));
                }
            }
        }
        Ok(())
    }

    /// xorshift64: deterministic, so a failure replays exactly.
    struct Rng(u64);

    impl Rng {
        fn below(&mut self, bound: u64) -> u64 {
            self.0 ^= self.0 << 13;
            self.0 ^= self.0 >> 7;
            self.0 ^= self.0 << 17;
            self.0 % bound
        }

        fn ids(&mut self, max_len: u64, bound: u64) -> Vec<EntityId> {
            (0..self.below(max_len + 1))
                .map(|_| self.below(bound))
                .collect()
        }
    }

    /// Drive every writer at random, including the unvalidated ones a scoped
    /// undo uses, so rows may share a target or repeat one. After each step the
    /// index must equal a rebuild from the rows, and the indexed check must
    /// answer a random batch exactly as the walk does.
    #[test]
    fn the_index_stays_exact_and_the_check_matches_the_walk() {
        for exclusive in [true, false] {
            let mut rng = Rng(0x9E37_79B9_7F4A_7C15 + u64::from(exclusive));
            let junction = RwLock::new(if exclusive {
                HashMapJunction::exclusive()
            } else {
                HashMapJunction::shared()
            });
            for step in 0..3000 {
                {
                    let mut jn = write_or_recover(&junction);
                    match rng.below(6) {
                        0..=2 => {
                            let (source, targets) = (rng.below(12), rng.ids(4, 16));
                            jn.insert(source, targets);
                        }
                        3 => {
                            jn.remove(&rng.below(12));
                        }
                        4 => jn.remove_target(&rng.below(16)),
                        // What snapshot, savepoint and restore do: swap in a clone.
                        _ => {
                            let copy = jn.clone();
                            *jn = copy;
                        }
                    }
                    if let Err(problem) = jn.check_index() {
                        panic!("exclusive={exclusive}, step {step}: {problem}");
                    }
                }
                let batch: Vec<(EntityId, Vec<EntityId>)> = (0..=rng.below(3))
                    .map(|_| (rng.below(12), rng.ids(2, 16)))
                    .collect();
                for scalar in [false, true] {
                    let walked = validate_by_walking(&read_or_recover(&junction), &batch, scalar);
                    let indexed = validate_junction_updates(&junction, &batch, scalar);
                    assert_eq!(
                        format!("{indexed:?}"),
                        format!("{walked:?}"),
                        "exclusive={exclusive}, step {step}, scalar={scalar}, batch {batch:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn a_transfer_within_one_batch_is_valid_but_not_from_outside_it() {
        let junction = RwLock::new(HashMapJunction::exclusive());
        junction_set(&junction, 1, vec![10, 11]);
        junction_set(&junction, 2, vec![20]);
        let check = |batch: &[(EntityId, Vec<EntityId>)]| {
            validate_junction_updates(&junction, batch, false)
        };
        assert!(check(&[(1, vec![11]), (2, vec![20, 10])]).is_ok());
        assert!(check(&[(2, vec![20, 10])]).is_err());
        assert!(check(&[(3, vec![10])]).is_err());
        assert!(check(&[(1, vec![]), (2, vec![10]), (3, vec![10])]).is_err());
        // Nothing to place: valid however full the junction is.
        assert!(check(&[(3, vec![]), (4, vec![])]).is_ok());
        // Deleting the owner, or the target, frees the target.
        junction_remove(&junction, &1);
        assert!(check(&[(3, vec![10])]).is_ok());
        delete_from_backward_junction(&junction, &20);
        assert!(check(&[(3, vec![20])]).is_ok());
        assert_eq!(junction_get(&junction, &2), Vec::<EntityId>::new());
        assert!(read_or_recover(&junction).check_index().is_ok());
    }
}
